local LuaTypeProviderFactory = require(script.Parent.Parent.Parent.Extensions.LuaTypeProviderFactory)
local HostBuilder = require(script.Parent.Parent.Hosting.HostBuilder)

return function(): IHostBuilder
	local manifest = game.ReplicatedStorage._robloxManifest
	local luaTypeProvider = LuaTypeProviderFactory(manifest.LuaTypes)
	local builder = HostBuilder.new(luaTypeProvider)
	return builder
end
